// Task 30: replays every scenario in web/src/engine/__fixtures__/parity.json
// (generated by tools/export_parity.py, the Python engine's own output --
// never reimplemented here) through the TS engine and asserts an exact
// match. Every scenario is deterministic (no seeded randomness) by
// construction -- see export_parity.py's header for why.
import type { Move as ChessJsMove, Square } from "chess.js";
import { Chess } from "chess.js";
import { readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import nflConfig from "../data/config/sports/nfl.json";
import parityFixture from "./__fixtures__/parity.json";
import { ContestConfig } from "./config";
import { loadEtrCsv, loadLineStats, loadOpeningBook } from "./loaders";
import { BuildState, KingMode, Piece, Player, Side } from "./models";
import { bookContinuations, openingName, rankFamilies, suggestOpening, type RankableLine } from "./openings";
import { classify, pieceForChessType } from "./pieces";
import type { ChessMove } from "./rules";
import {
  applyCaptureMove,
  applyMove,
  castle,
  isLegalCapture,
  isLegalMove,
  lineupStillCompletable,
  placeKings,
  switchKing,
} from "./rules";
import { loadSportConfig } from "./sport";

const dirname = path.dirname(fileURLToPath(import.meta.url));
const DATA_DIR = path.join(dirname, "..", "data");
const OPENINGS_DIR = path.join(DATA_DIR, "openings");
const SAMPLE_CSV_PATH = path.join(DATA_DIR, "samples", "NFL Weekly DFS System - Projections.csv");

const NFL = loadSportConfig(nflConfig);
const BOOK = loadOpeningBook(
  ["a", "b", "c", "d", "e"].map((letter) => readFileSync(path.join(OPENINGS_DIR, `${letter}.tsv`), "utf-8")),
);
const LINE_STATS = loadLineStats(readFileSync(path.join(OPENINGS_DIR, "line_stats.json"), "utf-8"));
const ETR_POOL = loadEtrCsv(readFileSync(SAMPLE_CSV_PATH, "utf-8"));

interface RawPlayer {
  id: string;
  name: string;
  positions: string[];
  team: string;
  opp: string;
  salary: number;
  proj: number;
  own_small: number;
  own_large: number;
}

function toPlayer(raw: RawPlayer): Player {
  return new Player({
    id: raw.id,
    name: raw.name,
    positions: raw.positions,
    team: raw.team,
    opp: raw.opp,
    salary: raw.salary,
    proj: raw.proj,
    ownSmall: raw.own_small,
    ownLarge: raw.own_large,
  });
}

function uci(move: string): ChessMove {
  return { from: move.slice(0, 2) as Square, to: move.slice(2, 4) as Square };
}

function playerIndex(raw: RawPlayer[]): Map<string, Player> {
  const map = new Map<string, Player>();
  for (const r of raw) map.set(r.id, toPlayer(r));
  return map;
}

interface SetupStep {
  move: string;
  player_id: string;
}

function replaySetup(
  setup: SetupStep[],
  byId: Map<string, Player>,
  contest: ContestConfig,
  initial: BuildState = new BuildState(),
): BuildState {
  let state = initial;
  for (const step of setup) {
    state = applyMove(state, uci(step.move), byId.get(step.player_id)!, NFL, contest);
  }
  return state;
}

function CONTEST(): ContestConfig {
  return new ContestConfig({ cap: 50000, fieldSize: 1000, payouts: [] });
}

interface Scenario {
  name: string;
  kind: string;
  [key: string]: unknown;
}

const scenarios = (parityFixture as { scenarios: Scenario[] }).scenarios;

describe("parity: Python vs TypeScript", () => {
  for (const scenario of scenarios) {
    it(`${scenario.name} (${scenario.kind})`, () => {
      runScenario(scenario);
    });
  }
});

function runScenario(scenario: Scenario): void {
  switch (scenario.kind) {
    case "classify_all_players":
      return checkClassifyAllPlayers(scenario);
    case "legal_move":
      return checkLegalMove(scenario);
    case "roster_completable":
      return checkRosterCompletable(scenario);
    case "castle":
      return checkCastle(scenario);
    case "switch_king":
      return checkSwitchKing(scenario);
    case "capture":
      return checkCapture(scenario);
    case "field_tier":
      return checkFieldTier(scenario);
    case "target_rank":
      return checkTargetRank(scenario);
    case "suggested_opening":
      return checkSuggestedOpening(scenario);
    case "family_ranking":
      return checkFamilyRanking(scenario);
    case "opening_lookup":
      return checkOpeningLookup(scenario);
    case "template_build":
      return checkTemplateBuild(scenario);
    default:
      throw new Error(`unknown parity scenario kind: ${scenario.kind}`);
  }
}

function checkClassifyAllPlayers(scenario: Scenario): void {
  const players = scenario.players as RawPlayer[];
  const expected = scenario.expected as { id: string; pieces: string[] }[];
  expect(players).toHaveLength(expected.length);
  const actual = players.map((raw) => ({ id: raw.id, pieces: [...classify(toPlayer(raw), NFL)].sort() }));
  const expectedTyped = expected.map((e) => ({ id: e.id, pieces: [...e.pieces].sort() }));
  expect(actual).toEqual(expectedTyped);
}

function checkLegalMove(scenario: Scenario): void {
  const byId = playerIndex(scenario.players as RawPlayer[]);
  const contest = new ContestConfig({ cap: scenario.cap as number, fieldSize: scenario.field_size as number, payouts: [] });
  const state = replaySetup(scenario.setup as SetupStep[], byId, contest);
  const move = uci(scenario.move as string);
  const player = byId.get(scenario.player_id as string)!;
  const expected = scenario.expected as {
    legal: boolean;
    san?: string;
    piece?: string;
    locked_player_ids?: string[];
  };

  const legal = isLegalMove(state, move, player, NFL, contest);
  expect(legal).toBe(expected.legal);
  if (!expected.legal) return;

  const newState = applyMove(state, move, player, NFL, contest);
  const sideMoves = newState.board.turn() === "b" ? newState.whiteMoves : newState.blackMoves;
  const record = sideMoves.find((m) => m.player.id === player.id)!;
  expect(record.san).toBe(expected.san);
  expect(record.piece).toBe(expected.piece);
  expect(Array.from(newState.lockedPlayerIds).sort()).toEqual(expected.locked_player_ids);
}

function checkRosterCompletable(scenario: Scenario): void {
  const players = (scenario.players as RawPlayer[]).map(toPlayer);
  const expected = scenario.expected as { completable: boolean };
  expect(lineupStillCompletable(players, NFL, scenario.cap as number)).toBe(expected.completable);
}

function checkCastle(scenario: Scenario): void {
  const byId = playerIndex(scenario.players as RawPlayer[]);
  const move = uci(scenario.move as string);
  const rook = byId.get(scenario.rook_player_id as string)!;
  const kingMode = scenario.king_mode === "PLACED" ? KingMode.PLACED : KingMode.EMERGE;

  let state: BuildState;
  if (kingMode === KingMode.EMERGE) {
    state = replaySetup(scenario.setup as SetupStep[], byId, CONTEST());
    const king = byId.get(scenario.king_player_id as string)!;
    const newState = castle(state, move, king, rook, NFL, CONTEST(), kingMode);
    const expected = scenario.expected as {
      san: string;
      locked_player_ids: string[];
      white_castled: boolean;
      king_piece: string;
      rook_piece: string;
    };
    const rookRecord = newState.whiteMoves.find((m) => m.player.id === rook.id)!;
    const kingRecord = newState.whiteMoves.find((m) => m.player.id === king.id)!;
    expect(rookRecord.san).toBe(expected.san);
    expect(Array.from(newState.lockedPlayerIds).sort()).toEqual(expected.locked_player_ids);
    expect(newState.whiteCastled).toBe(expected.white_castled);
    expect(kingRecord.piece).toBe(expected.king_piece);
    expect(rookRecord.piece).toBe(expected.rook_piece);
    return;
  }

  const whiteKing = byId.get(scenario.white_king_player_id as string)!;
  const blackKing = byId.get(scenario.black_king_player_id as string)!;
  state = placeKings(whiteKing, blackKing, NFL, CONTEST());
  state = replaySetup(scenario.setup as SetupStep[], byId, CONTEST(), state);
  const newState = castle(state, move, null, rook, NFL, CONTEST(), kingMode);
  const expected = scenario.expected as {
    san: string;
    locked_player_ids: string[];
    white_castled: boolean;
    rook_piece: string;
    king_move_count: number;
    king_player_id_after: string;
  };
  const rookRecord = newState.whiteMoves.find((m) => m.player.id === rook.id)!;
  expect(rookRecord.san).toBe(expected.san);
  expect(Array.from(newState.lockedPlayerIds).sort()).toEqual(expected.locked_player_ids);
  expect(newState.whiteCastled).toBe(expected.white_castled);
  expect(rookRecord.piece).toBe(expected.rook_piece);
  const kingMoves = newState.whiteMoves.filter((m) => m.piece === Piece.KING);
  expect(kingMoves).toHaveLength(expected.king_move_count);
  expect(kingMoves[0].player.id).toBe(expected.king_player_id_after);
}

function checkSwitchKing(scenario: Scenario): void {
  const byId = playerIndex(scenario.players as RawPlayer[]);
  const whiteKing = byId.get(scenario.white_king_player_id as string)!;
  const blackKing = byId.get(scenario.black_king_player_id as string)!;
  const rook = byId.get(scenario.rook_player_id as string)!;
  const newKing = byId.get(scenario.new_king_player_id as string)!;

  let state = placeKings(whiteKing, blackKing, NFL, CONTEST());
  state = replaySetup(scenario.setup as SetupStep[], byId, CONTEST(), state);
  state = castle(state, uci(scenario.castle_move as string), null, rook, NFL, CONTEST(), KingMode.PLACED);

  const side = scenario.side === "BLACK" ? Side.BLACK : Side.WHITE;
  const newState = switchKing(state, side, newKing, NFL, CONTEST());
  const expected = scenario.expected as { success: boolean; locked_player_ids?: string[]; king_player_id_after?: string };

  expect(newState !== null).toBe(expected.success);
  if (!expected.success || newState === null) return;
  expect(Array.from(newState.lockedPlayerIds).sort()).toEqual(expected.locked_player_ids);
  const kingMoves = newState.whiteMoves.filter((m) => m.piece === Piece.KING);
  expect(kingMoves[0].player.id).toBe(expected.king_player_id_after);
}

function checkCapture(scenario: Scenario): void {
  const byId = playerIndex(scenario.players as RawPlayer[]);
  let state: BuildState;
  if (scenario.fen) {
    state = new BuildState({ board: new Chess(scenario.fen as string) });
  } else {
    state = replaySetup(scenario.setup as SetupStep[], byId, CONTEST());
  }

  const move = uci(scenario.move as string);
  const replacementId = scenario.replacement_player_id as string | null;
  const replacement = replacementId === null ? null : byId.get(replacementId)!;

  const capturingSide = state.board.turn();
  if (replacement !== null) {
    expect(isLegalCapture(state, move, NFL, CONTEST())).toBe(false);
    expect(isLegalCapture(state, move, NFL, CONTEST(), replacement)).toBe(true);
  }
  const newState = applyCaptureMove(state, move, NFL, CONTEST(), replacement);

  const expected = scenario.expected as {
    san: string;
    captured_player_id: string;
    captured_piece?: string;
    white_moves_count: number;
    black_moves_count: number;
  };
  const sideMoves = capturingSide === "w" ? newState.whiteMoves : newState.blackMoves;
  const record = sideMoves.find((m) => m.player.id === expected.captured_player_id)!;
  expect(record.san).toBe(expected.san);
  if (expected.captured_piece) {
    expect(record.piece).toBe(expected.captured_piece);
  }
  expect(newState.whiteMoves).toHaveLength(expected.white_moves_count);
  expect(newState.blackMoves).toHaveLength(expected.black_moves_count);
}

function checkFieldTier(scenario: Scenario): void {
  const contest = new ContestConfig({ fieldSize: scenario.field_size as number, payouts: [] });
  const tier = contest.fieldTier();
  const expected = scenario.expected as { field_tier: string; own_for: number };
  expect(tier).toBe(expected.field_tier);
  const player = toPlayer(scenario.sample_player as RawPlayer);
  expect(player.ownFor(tier)).toBe(expected.own_for);
}

function checkTargetRank(scenario: Scenario): void {
  const contest = new ContestConfig({ fieldSize: scenario.field_size as number, payouts: [] });
  const expected = scenario.expected as { target_rank: number };
  expect(contest.targetRank(scenario.last_rank as number)).toBe(expected.target_rank);
}

function checkSuggestedOpening(scenario: Scenario): void {
  const ranked = rankFamilies(LINE_STATS as unknown as RankableLine[]);
  const contest = new ContestConfig({ fieldSize: scenario.field_size as number, payouts: [] });
  const suggestion = suggestOpening(contest, ranked);
  const expected = scenario.expected as { rank: number; name: string; games: number; eco: string; moves: string[] };
  expect(suggestion.rank).toBe(expected.rank);
  expect(suggestion.name).toBe(expected.name);
  expect(suggestion.games).toBe(expected.games);
  expect(suggestion.line.eco).toBe(expected.eco);
  expect(suggestion.line.moves).toEqual(expected.moves);
}

function checkFamilyRanking(scenario: Scenario): void {
  const ranked = rankFamilies(LINE_STATS as unknown as RankableLine[]);
  const actual = ranked.map((f) => ({ name: f.name, rank: f.rank, games: f.games, eco: f.line.eco, moves: [...f.line.moves] }));
  const expected = (scenario.expected as { families: typeof actual }).families;
  expect(actual).toEqual(expected);
}

function checkOpeningLookup(scenario: Scenario): void {
  const moves = scenario.moves as string[];
  const expected = scenario.expected as { opening_name: string | null; continuations: string[] };
  expect(openingName(moves, BOOK)).toBe(expected.opening_name);
  expect(Array.from(bookContinuations(moves, BOOK)).sort()).toEqual(expected.continuations);
}

function bestPlayerForMove(state: BuildState, move: ChessMove, piece: Piece, contest: ContestConfig): Player {
  const candidates = ETR_POOL.filter((p) => !state.lockedPlayerIds.has(p.id) && classify(p, NFL).has(piece)).sort(
    (a, b) => b.proj - a.proj,
  );
  for (const player of candidates) {
    if (isLegalMove(state, move, player, NFL, contest)) return player;
  }
  throw new Error(`no eligible player found for ${JSON.stringify(move)} (${piece})`);
}

function checkTemplateBuild(scenario: Scenario): void {
  const templateMoves = scenario.template_moves as string[];
  const contest = CONTEST();
  let state = new BuildState();
  const picks: { ply: number; side: string; san: string; piece: string; player_id: string; player_name: string }[] = [];

  templateMoves.forEach((san, index) => {
    const matched = state.board.moves({ verbose: true }).find((m: ChessJsMove) => m.san === san)!;
    const side = state.board.turn();
    const piece = pieceForChessType(matched.piece);
    const move: ChessMove = { from: matched.from, to: matched.to, promotion: matched.promotion };
    const player = bestPlayerForMove(state, move, piece, contest);
    state = applyMove(state, move, player, NFL, contest);
    picks.push({
      ply: index + 1,
      side: side === "w" ? "WHITE" : "BLACK",
      san,
      piece,
      player_id: player.id,
      player_name: player.name,
    });
  });

  const expected = scenario.expected as {
    picks: typeof picks;
    white_moves: typeof picks;
    black_moves: typeof picks;
    opening_name_at_end: string | null;
  };
  expect(picks).toEqual(expected.picks);
  expect(picks.filter((p) => p.side === "WHITE")).toEqual(expected.white_moves);
  expect(picks.filter((p) => p.side === "BLACK")).toEqual(expected.black_moves);
  expect(openingName(templateMoves, BOOK)).toBe(expected.opening_name_at_end);
}
